Fields(CStream_AC* aStream);	virtual void WriteFields(CStream_AC* aStream) const;	//------------------------------------------------------------------------------------	// MacApp overrides.	//------------------------------------------------------------------------------------	virtual IDType GetStandardSignature() const;		// Return the signature of this view.	//------------------------------------------------------------------------------------	// Disclosure control.	//------------------------------------------------------------------------------------		void SetDisclosed(bool isDisclosed, bool redraw);		bool IsDisclosed() const;		virtual CControl_AC* DoMakeControl(WindowRef theWindow,										const CRect_AC& boundsRect, 										bool isVisible, bool isEnabled, 										const CStr255_AC& itsTitle);protected:	bool fInitialDisclosed;};#if qAppearance//----------------------------------------------------------------------------------------// TLeftFacingDisclosureTriangle//----------------------------------------------------------------------------------------class EXPORT_MA TLeftFacingDisclosureTriangle : public TDisclosureTriangle// Implements a left facing disclosure triangle control.// Behaves similar to a check box -- it's either on or off.{	MA_DECLARE_CLASS;public:	// TControl-compatible constructor	TLeftFacingDisclosureTriangle(const CViewPoint& itsLocation = gZeroVPt,							 const CViewPoint& itsSize = gZeroVPt,							 SizeDeterminer itsHSizeDet = sizeVariable,							 SizeDeterminer itsVSizeDet = sizeVariable,						     bool isDisclosed = false);	TLeftFacingDisclosureTriangle(const TLeftFacingDisclosureTriangle& inDisclosureTriangle);		// Copy Constructor	virtual ~TLeftFacingDisclosureTriangle();	//------------------------------------------------------------------------------------	// MacApp overrides.	//------------------------------------------------------------------------------------	virtual IDType GetStandardSignature() const;		// Return the signature of this view.	//------------------------------------------------------------------------------------	// Disclosure control.	//------------------------------------------------------------------------------------			virtual CControl_AC* DoMakeControl(WindowRef theWindow,										const CRect_AC& boundsRect, 										bool isVisible, bool isEnabled, 										const CStr255_AC& itsTitle);};#endif // qAppearance#endif // qAppearance || qEmulateStandardControls#endif // __UDISCLOSURETRIANGLE__